H({
  id: 'hd-next-date', title: 'Next Day and Day of the Year', topic: 'Selection (hard)',
  desc: `<p>For the date <code>day</code>/<code>month</code>/<code>year</code> print <code>Day of year: n</code>, <code>Next day: d/m/y</code> and <code>Leap year: Yes</code> or <code>No</code>.
A leap year is divisible by 4 but not by 100, or divisible by 400. An impossible date (or year below 1) prints <code>Invalid date.</code></p>
<pre class="formula">Day of year: 366
Next day: 1/1/2025
Leap year: Yes</pre>`,
  template: T(),
  tests: hide([v('int day = 31, month = 12, year = 2024;'), v('int day = 28, month = 2, year = 2023;'), v('int day = 28, month = 2, year = 2024;'), v('int day = 29, month = 2, year = 2023;'),
    v('int day = 30, month = 4, year = 2026;'), v('int day = 31, month = 4, year = 2026;'), v('int day = 1, month = 1, year = 2000;'), v('int day = 29, month = 2, year = 1900;'),
    v('int day = 15, month = 8, year = 1957;'), v('int day = 31, month = 1, year = 2100;')]),
  solution: `bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
int dim = 0;
if (month == 2) dim = leap ? 29 : 28;
else if (month == 4 || month == 6 || month == 9 || month == 11) dim = 30;
else if (month >= 1 && month <= 12) dim = 31;
if (year < 1 || dim == 0 || day < 1 || day > dim) {
    cout << "Invalid date." << endl;
} else {
    int doy = day;
    for (int m = 1; m < month; m++) {
        int d;
        if (m == 2) d = leap ? 29 : 28;
        else if (m == 4 || m == 6 || m == 9 || m == 11) d = 30;
        else d = 31;
        doy += d;
    }
    int nd = day + 1, nm = month, ny = year;
    if (nd > dim) {
        nd = 1;
        nm++;
        if (nm > 12) { nm = 1; ny++; }
    }
    cout << "Day of year: " << doy << endl;
    cout << "Next day: " << nd << "/" << nm << "/" << ny << endl;
    cout << "Leap year: " << (leap ? "Yes" : "No") << endl;
}`,
}),
H({
  id: 'hd-weekday', title: 'Day of the Week (Zeller)', topic: 'Selection (hard)',
  desc: `<p>Find the weekday of <code>day</code>/<code>month</code>/<code>year</code> (years 1900 – 2100) with Zeller's congruence:
if the month is January or February, use month + 12 of the previous year. With K = year % 100 and J = year / 100:</p>
<pre class="formula">h = (day + 13 × (month + 1) / 5 + K + K / 4 + J / 4 + 5 × J) % 7</pre>
<p>(integer division). h = 0 Saturday, 1 Sunday, 2 Monday, … 6 Friday. Print <code>29/10/2026 is a Thursday.</code> and then
<code>It is a weekend.</code> or <code>It is a weekday.</code> An impossible date or a year outside 1900 – 2100 prints <code>Invalid date.</code></p>`,
  template: T(),
  tests: hide([v('int day = 29, month = 10, year = 2026;'), v('int day = 1, month = 1, year = 2000;'), v('int day = 31, month = 8, year = 1957;'), v('int day = 29, month = 2, year = 2023;'),
    v('int day = 25, month = 12, year = 2025;'), v('int day = 1, month = 1, year = 1899;'), v('int day = 29, month = 2, year = 2000;'), v('int day = 15, month = 2, year = 2100;'),
    v('int day = 31, month = 6, year = 2026;'), v('int day = 16, month = 9, year = 1963;')]),
  solution: `bool leap = (year % 4 == 0 && year % 100 != 0) || year % 400 == 0;
int dim = 0;
if (month == 2) dim = leap ? 29 : 28;
else if (month == 4 || month == 6 || month == 9 || month == 11) dim = 30;
else if (month >= 1 && month <= 12) dim = 31;
if (year < 1900 || year > 2100 || dim == 0 || day < 1 || day > dim) {
    cout << "Invalid date." << endl;
} else {
    int m = month, y = year;
    if (m < 3) { m += 12; y--; }
    int K = y % 100, J = y / 100;
    int h = (day + 13 * (m + 1) / 5 + K + K / 4 + J / 4 + 5 * J) % 7;
    cout << day << "/" << month << "/" << year << " is a ";
    if (h == 0) cout << "Saturday";
    else if (h == 1) cout << "Sunday";
    else if (h == 2) cout << "Monday";
    else if (h == 3) cout << "Tuesday";
    else if (h == 4) cout << "Wednesday";
    else if (h == 5) cout << "Thursday";
    else cout << "Friday";
    cout << "." << endl;
    cout << (h == 0 || h == 1 ? "It is a weekend." : "It is a weekday.") << endl;
}`,
})
